create or replace function public.property_media_orientation()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'UPDATE' then
    if new.variants is not distinct from old.variants then
      return new;
    end if;
  end if;
  if new.variants ? 'hero' then
    new.orientation := case
      when (new.variants -> 'hero' ->> 'h')::int < (new.variants -> 'hero' ->> 'w')::int
        then 'portrait'::public.media_orientation
      else 'landscape'::public.media_orientation
    end;
  end if;
  return new;
end;
$$;

create or replace function public.sync_property_hero_image()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_ids uuid[];
  v_property_id uuid;
  v_key text;
begin
  if tg_op = 'INSERT' then
    v_ids := array[new.property_id];
  elsif tg_op = 'DELETE' then
    v_ids := array[old.property_id];
  else
    v_ids := array[old.property_id, new.property_id];
  end if;
  foreach v_property_id in array v_ids loop
    select m.media_key into v_key
    from public.property_media m
    where m.property_id = v_property_id
    order by m.sort_order desc, m.id
    limit 1;
    update public.properties
    set hero_image = v_key
    where id = v_property_id
      and hero_image is distinct from v_key;
  end loop;
  return null;
end;
$$;

create or replace function public.enforce_submission_media_limit()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- GQ-07: the row lock makes concurrent inserts for one submission run one after another, so the count is exact.
  perform 1 from public.submissions where id = new.submission_id for update;
  if (select count(*) from public.submission_media where submission_id = new.submission_id) >= 41 then
    raise exception 'upload_limit';
  end if;
  return new;
end;
$$

